#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <jni.h>
#include <grpc/grpc.h>
#include <grpc/support/log.h>

/* JNI-backed gRPC service with async request processing */

typedef struct {
    JavaVM *jvm;
    jobject classifier_ref;
    jmethodID classify_method;
    pthread_mutex_t jni_lock;
    int ref_count;
    int shutting_down;
} jni_context_t;

typedef struct {
    char *payload;
    size_t payload_len;
    jni_context_t *ctx;
    void (*completion_cb)(int result, void *user_data);
    void *user_data;
} async_task_t;

static jni_context_t *g_ctx = NULL;

static int init_jni_context(const char *classpath) {
    JavaVMInitArgs vm_args;
    JavaVMOption options[1];
    JNIEnv *env;
    jclass cls;

    char cp_opt[512];
    snprintf(cp_opt, sizeof(cp_opt), "-Djava.class.path=%s", classpath);
    options[0].optionString = cp_opt;

    vm_args.version = JNI_VERSION_1_8;
    vm_args.nOptions = 1;
    vm_args.options = options;
    vm_args.ignoreUnrecognized = JNI_FALSE;

    g_ctx = calloc(1, sizeof(jni_context_t));
    if (!g_ctx) return -1;

    if (JNI_CreateJavaVM(&g_ctx->jvm, (void**)&env, &vm_args) != JNI_OK) {
        free(g_ctx);
        g_ctx = NULL;
        return -1;
    }

    cls = (*env)->FindClass(env, "com/service/PayloadClassifier");
    if (!cls) return -1;

    jmethodID ctor = (*env)->GetMethodID(env, cls, "<init>", "()V");
    jobject obj = (*env)->NewObject(env, cls, ctor);
    g_ctx->classifier_ref = (*env)->NewGlobalRef(env, obj);
    g_ctx->classify_method = (*env)->GetMethodID(env, cls, "classify", "([B)I");

    pthread_mutex_init(&g_ctx->jni_lock, NULL);
    g_ctx->ref_count = 1;
    g_ctx->shutting_down = 0;
    return 0;
}

/* Detach policy: track per-thread attachment state */
static __thread int t_attached = 0;

static JNIEnv *get_env(jni_context_t *ctx) {
    JNIEnv *env = NULL;
    jint rc = (*ctx->jvm)->GetEnv(ctx->jvm, (void**)&env, JNI_VERSION_1_8);
    if (rc == JNI_EDETACHED) {
        (*ctx->jvm)->AttachCurrentThread(ctx->jvm, (void**)&env, NULL);
        t_attached = 1;
    }
    return env;
}

static void release_env(jni_context_t *ctx) {
    if (t_attached) {
        (*ctx->jvm)->DetachCurrentThread(ctx->jvm);
        t_attached = 0;
    }
}

/* Core classification - called from worker threads */
static int do_classify(jni_context_t *ctx, const char *data, size_t len) {
    JNIEnv *env;
    int result;

    pthread_mutex_lock(&ctx->jni_lock);
    if (ctx->shutting_down) {
        pthread_mutex_unlock(&ctx->jni_lock);
        return -1;
    }
    ctx->ref_count++;
    pthread_mutex_unlock(&ctx->jni_lock);

    env = get_env(ctx);
    if (!env) {
        pthread_mutex_lock(&ctx->jni_lock);
        ctx->ref_count--;
        pthread_mutex_unlock(&ctx->jni_lock);
        return -1;
    }

    jbyteArray jarr = (*env)->NewByteArray(env, (jsize)len);
    if (!jarr) {
        if ((*env)->ExceptionCheck(env)) {
            (*env)->ExceptionClear(env);
        }
        release_env(ctx);
        pthread_mutex_lock(&ctx->jni_lock);
        ctx->ref_count--;
        pthread_mutex_unlock(&ctx->jni_lock);
        return -1;
    }
    (*env)->SetByteArrayRegion(env, jarr, 0, (jsize)len, (const jbyte*)data);

    jint jresult = (*env)->CallIntMethod(env, ctx->classifier_ref, ctx->classify_method, jarr);

    if ((*env)->ExceptionCheck(env)) {
        (*env)->ExceptionClear(env);
        jresult = -1;
    }

    (*env)->DeleteLocalRef(env, jarr);
    release_env(ctx);

    result = (int)jresult;

    pthread_mutex_lock(&ctx->jni_lock);
    ctx->ref_count--;
    pthread_mutex_unlock(&ctx->jni_lock);

    return result;
}

/* Async worker thread function */
static void *async_worker(void *arg) {
    async_task_t *task = (async_task_t *)arg;

    int result = do_classify(task->ctx, task->payload, task->payload_len);

    if (task->completion_cb) {
        task->completion_cb(result, task->user_data);
    }

    free(task->payload);
    free(task);
    return NULL;
}

/* Submit async classification - called from gRPC handler */
static int submit_async_classify(const char *payload, size_t len,
                                  void (*cb)(int, void*), void *ud) {
    if (!g_ctx || len == 0) return -1;

    pthread_mutex_lock(&g_ctx->jni_lock);
    if (g_ctx->shutting_down) {
        pthread_mutex_unlock(&g_ctx->jni_lock);
        return -1;
    }
    pthread_mutex_unlock(&g_ctx->jni_lock);

    async_task_t *task = malloc(sizeof(async_task_t));
    if (!task) return -1;

    task->payload = malloc(len);
    if (!task->payload) { free(task); return -1; }
    memcpy(task->payload, payload, len);
    task->payload_len = len;
    task->ctx = g_ctx;
    task->completion_cb = cb;
    task->user_data = ud;

    pthread_t tid;
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);

    if (pthread_create(&tid, &attr, async_worker, task) != 0) {
        free(task->payload);
        free(task);
        pthread_attr_destroy(&attr);
        return -1;
    }

    pthread_attr_destroy(&attr);
    return 0;
}

/* Shutdown: set flag, wait for workers, then destroy */
static void shutdown_jni_context(void) {
    if (!g_ctx) return;

    pthread_mutex_lock(&g_ctx->jni_lock);
    g_ctx->shutting_down = 1;
    pthread_mutex_unlock(&g_ctx->jni_lock);

    /* Spin-wait for all workers to complete */
    int active;
    do {
        pthread_mutex_lock(&g_ctx->jni_lock);
        active = g_ctx->ref_count;
        pthread_mutex_unlock(&g_ctx->jni_lock);
        if (active > 1) {
            struct timespec ts = {0, 10000000}; /* 10ms */
            nanosleep(&ts, NULL);
        }
    } while (active > 1);

    JNIEnv *env = get_env(g_ctx);
    (*env)->DeleteGlobalRef(env, g_ctx->classifier_ref);
    (*g_ctx->jvm)->DestroyJavaVM(g_ctx->jvm);
    pthread_mutex_destroy(&g_ctx->jni_lock);
    free(g_ctx);
    g_ctx = NULL;
}

/* gRPC unary handler simulation */
static void handle_classify_request(grpc_byte_buffer *request_bb) {
    grpc_byte_buffer_reader reader;
    grpc_byte_buffer_reader_init(&reader, request_bb);
    grpc_slice slice = grpc_byte_buffer_reader_readall(&reader);

    const char *data = (const char *)GRPC_SLICE_START_PTR(slice);
    size_t data_len = GRPC_SLICE_LENGTH(slice);

    submit_async_classify(data, data_len, NULL, NULL);

    grpc_slice_unref(slice);
    grpc_byte_buffer_reader_destroy(&reader);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <classpath>\n", argv[0]);
        return 1;
    }

    grpc_init();

    if (init_jni_context(argv[1]) != 0) {
        fprintf(stderr, "Failed to initialize JNI context\n");
        return 1;
    }

    gpr_log(GPR_INFO, "gRPC+JNI service started");

    /* Main event loop would go here */
    /* ... */

    shutdown_jni_context();
    grpc_shutdown();
    return 0;
}
